class Text extends m.StatelessWidget {
 final String data;final m.TextStyle? style;final m.TextAlign? textAlign;final int? maxLines;final m.TextOverflow? overflow;
 const Text(this.data,{super.key,this.style,this.textAlign,this.maxLines,this.overflow});
 @override m.Widget build(m.BuildContext context){m.Localizations.localeOf(context);return m.Text(L.text(data),style:style,textAlign:textAlign,maxLines:maxLines,overflow:overflow);}
